                maxA = aSpell[i];
                maxB = bSpell[i];
            }
        }

        long[] aMeal = new long[M];
        long[] bMeal = new long[M];
        for (int i = 0; i < M; i++) aMeal[i] = fs.nextLong();
        for (int i = 0; i < M; i++) bMeal[i] = fs.nextLong();

        // Sort meals by c = b / (a - 1) descending. a == 1 means c = infinity.
        Integer[] mealIdx = new Integer[M];
