            long maxImmediate = best.m * x + best.c;
            long spellVal = (C * (maxImmediate % MOD) + D) % MOD;
            long ans = (A_meal * spellVal + B_meal) % MOD;
            sb.append(ans).append('\n');
        }

        System.out.print(sb);
    }
}
